#' @importFrom SeuratObject CreateSeuratObject
#' @keywords internal
"_PACKAGE"

#' Load the combined 10x Genomics PBMC single-cell reference or its pseudo-bulk
#'
#' Loads either the processed single-cell RNA-seq reference generated by
#' combining publicly available peripheral blood mononuclear cell (PBMC)
#' datasets from healthy donors provided by 10x Genomics, or the pseudo-bulk
#' training data simulated from that reference.
#'
#' The single-cell reference combines the 6k PBMC, 8k PBMC, and 10k PBMC
#' datasets and was processed, annotated, filtered, and formatted for use in
#' QUASAR deconvolution workflows. It is a processed Seurat object containing
#' 22,629 features across 21,978 cells. The active assay is `RNA`, with 22,629
#' features and 0 variable features. The assay contains only one layer:
#' `counts`.
#'
#' Cell type annotations are stored in the object metadata column `celltype`.
#' The dataset contains the following annotated cell types:
#'
#' \describe{
#'   \item{Bcells}{3,352 cells}
#'   \item{CD4Tcells}{8,181 cells}
#'   \item{CD8Tcells}{3,329 cells}
#'   \item{Monocytes}{5,428 cells}
#'   \item{NK}{1,586 cells}
#'   \item{Unknown}{102 cells}
#' }
#'
#' Dataset-of-origin information is stored in the metadata column `donor_id`.
#' The combined reference contains:
#'
#' \describe{
#'   \item{pbmc10k}{9,141 cells}
#'   \item{pbmc6k}{4,658 cells}
#'   \item{pbmc8k}{8,179 cells}
#' }
#'
#' The original 10x Genomics datasets are licensed under the Creative Commons
#' Attribution 4.0 International License (CC BY 4.0). The data included here
#' were processed, annotated, filtered, and reformatted by Sergej Ruff. No
#' endorsement by 10x Genomics is implied.
#'
#' @param which Which dataset to load. One of:
#'   \itemize{
#'     \item \code{"ref"} (the default): the combined single-cell Seurat
#'       reference.
#'     \item \code{"pseudobulk"}: pseudo-bulk profiles simulated from that
#'       reference, together with their ground-truth cell-type proportions.
#'   }
#'
#' @return If \code{which = "ref"}, a processed Seurat object with 22,629
#'   features and 21,978 cells. The object contains one assay, `RNA`, with the
#'   layer `counts`. Cell type labels are stored in `celltype`, and
#'   dataset-origin labels are stored in `donor_id`.
#'
#'   If \code{which = "pseudobulk"}, a list with:
#'   \itemize{
#'     \item \code{bulk_expression_profiles}: pseudo-bulk expression matrix
#'       (features x samples).
#'     \item \code{ground_truth_proportions}: true cell-type proportions
#'       (samples x cell types).
#'     \item \code{cells_per_sample}: number of cells aggregated per
#'       pseudo-bulk sample.
#'   }
#'
#' @details
#' The pseudo-bulk data is stored across
#' \code{pbmc_healthy_pb_1.rds} ... \code{pbmc_healthy_pb_10.rds} to keep
#' individual files small. It is reassembled into a single dataset on load, so
#' the split is not visible to the caller. Sample order is preserved.
#'
#' The pseudo-bulk profiles are intended as training data for deconvolution
#' methods that learn from simulated mixtures, with the single-cell object
#' serving as the underlying reference.
#'
#' @source
#' 10x Genomics:
#' \itemize{
#'   \item 6k PBMCs from a Healthy Donor, Universal 3' dataset analyzed using Cell Ranger 1.1.0.
#'   \item 8k PBMCs from a Healthy Donor, Universal 3' dataset analyzed using Cell Ranger 2.1.0.
#'   \item 10k PBMCs from a Healthy Donor (v3 chemistry), Universal 3' dataset analyzed using Cell Ranger 3.0.0.
#' }
#'
#' Original datasets: \url{https://www.10xgenomics.com/resources/datasets}
#'
#' License: Creative Commons Attribution 4.0 International,
#' \url{https://creativecommons.org/licenses/by/4.0/}
#'
#' @examples
#'
#' pbmc_sc_ref <- load_pbmc_sc_ref()
#'
#' pbmc_sc_ref
#'
#' table(pbmc_sc_ref$celltype)
#' table(pbmc_sc_ref$donor_id)
#'
#' \dontrun{
#' pb <- load_pbmc_sc_ref("pseudobulk")
#'
#' dim(pb$bulk_expression_profiles)
#' dim(pb$ground_truth_proportions)
#' }
#'
#' @export
load_pbmc_sc_ref <- function(which = c("ref", "pseudobulk")) {
  which <- match.arg(which)

  if (identical(which, "ref")) {
    path <- system.file(
      "extdata",
      "pbmc_sc_ref.rds",
      package = "QuasarDeconData",
      mustWork = TRUE
    )

    return(readRDS(path))
  }

  n_chunks <- 10L
  files <- sprintf("pbmc_healthy_pb_%d.rds", seq_len(n_chunks))

  paths <- vapply(
    files,
    function(x) system.file("extdata", x, package = "QuasarDeconData"),
    character(1)
  )

  missing_files <- !nzchar(paths) | !file.exists(paths)

  if (any(missing_files)) {
    stop(
      "Packaged pseudo-bulk file(s) not found: ",
      paste(files[missing_files], collapse = ", "),
      call. = FALSE
    )
  }

  out <- lapply(paths, readRDS)

  sample_axis <- attr(out[[1]], "sample_axis")
  if (is.null(sample_axis)) sample_axis <- "cols"

  expr_parts <- lapply(out, `[[`, "bulk_expression_profiles")
  prop_parts <- lapply(out, `[[`, "ground_truth_proportions")

  expr <- if (identical(sample_axis, "cols")) {
    do.call(cbind, expr_parts)
  } else {
    do.call(rbind, expr_parts)
  }
  prop <- do.call(rbind, prop_parts)

  cps_parts <- lapply(out, `[[`, "cells_per_sample")
  cps <- if (all(vapply(cps_parts, length, integer(1)) == 1L) &&
             length(unique(unlist(cps_parts))) == 1L) {
    cps_parts[[1]]
  } else {
    unlist(cps_parts, use.names = FALSE)
  }

  rm(out, expr_parts, prop_parts, cps_parts)

  n_expr <- if (identical(sample_axis, "cols")) ncol(expr) else nrow(expr)
  if (n_expr != nrow(prop)) {
    stop(
      "Reassembled pseudo-bulk data is inconsistent: ",
      n_expr, " expression samples vs ", nrow(prop), " proportion rows.",
      call. = FALSE
    )
  }

  list(
    bulk_expression_profiles = expr,
    ground_truth_proportions = prop,
    cells_per_sample = cps
  )
}



#' Processed GSE107011 PBMC bulk deconvolution dataset
#'
#' A processed peripheral blood mononuclear cell (PBMC) bulk RNA-seq
#' deconvolution dataset derived from GEO accession GSE107011. The original
#' study profiled immune cell types and PBMC samples and used the data for
#' transcriptomic characterization and deconvolution analyses.
#'
#' The object is provided as a named list with bulk expression profiles,
#' experimentally derived ground-truth cell type proportions, and gene
#' identifiers. It was processed and formatted for use in QUASAR deconvolution
#' workflows.
#'
#' The object contains the following elements:
#'
#' \describe{
#'   \item{ground_truth_proportions}{
#'     A numeric matrix or data frame with 12 samples and 6 cell type columns.
#'     The columns are `Bcells`, `CD4Tcells`, `CD8Tcells`, `Monocytes`, `NK`,
#'     and `Unknown`.
#'   }
#'   \item{bulk_expression_profiles}{
#'     A numeric matrix or data frame with 36,128 features and 12 bulk PBMC
#'     samples.
#'   }
#'   \item{ensembl_ids}{
#'     Gene identifiers corresponding to the rows of `bulk_expression_profiles`.
#'   }
#' }
#'
#' Ground-truth cell type proportions are available for the following cell
#' types:
#'
#' \describe{
#'   \item{Bcells}{B cells}
#'   \item{CD4Tcells}{CD4 T cells}
#'   \item{CD8Tcells}{CD8 T cells}
#'   \item{Monocytes}{Monocytes}
#'   \item{NK}{Natural killer cells}
#'   \item{Unknown}{Unassigned or remaining cell type fraction}
#' }
#'
#' The data included here were processed and reformatted by Sergej Ruff for use
#' with QUASAR deconvolution workflows. No endorsement by the original data
#' providers is implied.
#'
#' @format A named list with three elements:
#' \describe{
#'   \item{ground_truth_proportions}{
#'     A 12 x 6 matrix or data frame containing ground-truth PBMC cell type
#'     proportions.
#'   }
#'   \item{bulk_expression_profiles}{
#'     A 36,128 x 12 matrix or data frame containing bulk expression profiles.
#'   }
#'   \item{ensembl_ids}{
#'     A vector of Ensembl gene identifiers corresponding to the expression
#'     profile rows.
#'   }
#' }
#'
#' @source
#' Gene Expression Omnibus accession GSE107011:
#' \url{https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE107011}
#'
#' Monaco G, Lee B, Xu W, Mustafah S, Hwang YY, Carré C, Burdin N,
#' Visan L, Ceccarelli M, Poidinger M, Zippelius A, Pedro de Magalhães J,
#' Larbi A. RNA-Seq Signatures Normalized by mRNA Abundance Allow Absolute
#' Deconvolution of Human Immune Cell Types. Cell Reports.
#'
#' @usage data(GSE107011)
#'
#' @keywords datasets
#'
#' @examples
#' data(GSE107011)
#'
#' names(GSE107011)
#' dim(GSE107011$bulk_expression_profiles)
#' dim(GSE107011$ground_truth_proportions)
#' colnames(GSE107011$ground_truth_proportions)
"GSE107011"


