#' Processed SDY67 PBMC bulk deconvolution dataset
#'
#' A processed peripheral blood mononuclear cell (PBMC) bulk RNA-seq
#' deconvolution dataset derived from ImmPort study SDY67. Bulk expression
#' profiles were matched to flow cytometry measurements using participant
#' identifiers, collection visits, and collection-time metadata.
#'
#' The object contains bulk expression profiles and flow-derived reference
#' cell type proportions for 231 matched samples. It was processed and
#' formatted for use in QUASAR deconvolution workflows.
#'
#' @format A named list with two elements:
#' \describe{
#'   \item{bulk_expression_profiles}{
#'     A numeric matrix or data frame with 23,113 genes and 231 bulk samples.
#'     Gene symbols are stored as row names and RNA experiment-sample
#'     accessions are stored as column names. Expression values are
#'     preserved from the supplied source matrices.
#'   }
#'   \item{ground_truth_proportions}{
#'     A numeric matrix or data frame with 231 samples and 6 columns:
#'     \code{CD8Tcells}, \code{Monocytes}, \code{CD4Tcells},
#'     \code{Bcells}, \code{NK}, and \code{Unknown}.
#'     Values are fractions on a 0--1 scale. Row names match the column
#'     names of \code{bulk_expression_profiles} in exactly the same order.
#'   }
#' }
#'
#' @details
#' Proportions were extracted from saved FlowJo population counts in the
#' innate and Treg panels. Each population count was divided by the
#' \code{Live cells} count from the same panel and sample run.
#'
#' The six columns were constructed as follows:
#'
#' \describe{
#'   \item{CD8Tcells}{
#'     The study-labeled \code{CD8+ T cells} gate within the Treg panel's
#'     \code{CD3+ gate}. This gate identifies CD4-low or CD4-negative
#'     T cells and is a proxy for CD8 T cells. The panel does not contain
#'     a CD8 antibody channel.
#'   }
#'   \item{Monocytes}{
#'     The sum of classical, intermediate, and non-classical monocyte
#'     fractions below the innate panel's \code{DR+ Non B cells} gate.
#'     Alternative source labels, including \code{Conventional monocytes}
#'     and \code{Non-conventional monocytes}, were treated as aliases of
#'     the corresponding subsets, not as additional populations.
#'   }
#'   \item{CD4Tcells}{
#'     The \code{CD4+ T cells} gate within the Treg panel's
#'     \code{CD3+ gate}. Nested populations, including regulatory T cells,
#'     were not added separately.
#'   }
#'   \item{Bcells}{
#'     The innate panel's \code{B cells} gate. Measurements from the
#'     separate B-cell panel were not combined with this estimate.
#'   }
#'   \item{NK}{
#'     The innate panel's \code{NK cells} gate. The separately gated
#'     \code{NK T cells} population is not included.
#'   }
#'   \item{Unknown}{
#'     The arithmetic remainder:
#'     \code{1 - (CD8Tcells + Monocytes + CD4Tcells + Bcells + NK)}.
#'     This is not a directly measured population or an explicit sum
#'     of the remaining named gates.
#'   }
#' }
#'
#' Samples with missing or ambiguous panel matches, or overlapping interiors
#' of the main CD4 and CD8-proxy gates, were excluded. The retained samples
#' have complete values for all six proportion columns.
#'
#' The proportions combine measurements from two flow panels. Consequently,
#' \code{Unknown} can include unassigned cells and differences between
#' panel-specific gates. The six columns sum to one by construction, but
#' should be interpreted as an approximate composition rather than an
#' exhaustive measurement of mutually exclusive populations.
#'
#' RNA and flow measurements were paired by participant and collection
#' visit. Their biosample accessions differ, so matching does not establish
#' that both assays used the identical aliquot.
#'
#' The data included here were processed and reformatted by Sergej Ruff for
#' use with QUASAR deconvolution workflows. No endorsement by the original
#' data providers is implied.
#'
#' @source
#' ImmPort study SDY67, release DR58:
#' \url{https://www.immport.org/shared/study/SDY67}
#'
#' Cell proportions were extracted from the supplied innate and Treg
#' FlowJo workspaces and linked to RNA samples using the study metadata.
#'
#' @usage data(SDY67)
#'
#' @keywords datasets
#'
#' @examples
#' data(SDY67)
#'
#' names(SDY67)
#' dim(SDY67$bulk_expression_profiles)
#' dim(SDY67$ground_truth_proportions)
#' colnames(SDY67$ground_truth_proportions)
#'
#' identical(
#'   colnames(SDY67$bulk_expression_profiles),
#'   rownames(SDY67$ground_truth_proportions)
#' )
"SDY67"

#' Processed GSE193141 PBMC bulk deconvolution dataset
#'
#' A processed peripheral blood mononuclear cell (PBMC) bulk RNA-seq
#' deconvolution dataset derived from GEO accession GSE193141. The original
#' study generated matched transcriptomic and flow cytometry measurements
#' to investigate age-related changes in human PBMCs.
#'
#' The object contains bulk expression profiles, six-column reference
#' proportions, and the eight original flow cytometry population
#' measurements for 156 matched samples. It was processed and formatted
#' for use in QUASAR deconvolution workflows.
#'
#' @format A named list with three elements:
#' \describe{
#'   \item{bulk_expression_profiles}{
#'     A numeric matrix or data frame with 39,376 genes and 156 bulk
#'     samples. Values are the supplied raw expression counts.
#'     NCBI gene identifiers are stored as row names and RNA GSM
#'     accessions are stored as column names.
#'   }
#'   \item{ground_truth_proportions}{
#'     A numeric matrix or data frame with 156 samples and 6 columns:
#'     \code{CD8Tcells}, \code{Monocytes}, \code{CD4Tcells},
#'     \code{Bcells}, \code{NK}, and \code{Unknown}.
#'     Values are fractions on a 0--1 scale.
#'   }
#'   \item{ground_truth_all_ct}{
#'     A numeric matrix or data frame with 156 samples and 8 columns:
#'     \code{Monocytes}, \code{Granulocytes}, \code{Lymphocytes},
#'     \code{B_Cells}, \code{NK_Cells}, \code{T_Cells},
#'     \code{CD4_T_Cells}, and \code{CD8_T_Cells}.
#'     These are the original reported population percentages divided
#'     by 100. Parent populations and their subsets overlap.
#'   }
#' }
#'
#' @details
#' Samples were matched using the \code{GSM_rna} identifiers in the
#' supplementary metadata. Three expression samples without cell
#' proportion measurements were excluded, leaving 156 matched samples.
#' The row names of both proportion matrices match the column names of
#' \code{bulk_expression_profiles} in exactly the same order.
#'
#' The five selected cell types map directly to source columns:
#'
#' \describe{
#'   \item{CD8Tcells}{
#'     The source \code{CD8_T_Cells} percentage divided by 100.
#'   }
#'   \item{Monocytes}{
#'     The source \code{Monocytes} percentage divided by 100.
#'   }
#'   \item{CD4Tcells}{
#'     The source \code{CD4_T_Cells} percentage divided by 100.
#'   }
#'   \item{Bcells}{
#'     The source \code{B_Cells} percentage divided by 100.
#'   }
#'   \item{NK}{
#'     The source \code{NK_Cells} percentage divided by 100.
#'   }
#'   \item{Unknown}{
#'     The arithmetic remainder:
#'     \code{1 - (CD8Tcells + Monocytes + CD4Tcells + Bcells + NK)}.
#'     This is a derived residual rather than a directly measured
#'     population.
#'   }
#' }
#'
#' No source populations were combined to construct the five selected
#' cell type columns. Granulocytes, total lymphocytes, and total T cells
#' are retained in \code{ground_truth_all_ct} for additional context.
#'
#' The additional columns must not be summed to calculate \code{Unknown}.
#' Total lymphocytes overlap B, NK, and T cells, while total T cells
#' overlap CD4 and CD8 T cells. The residual can include granulocytes,
#' other lymphocyte populations, unclassified fractions, and effects of
#' gating. Its exact biological membership cannot be determined from
#' these summary measurements alone.
#'
#' The six-column proportion matrix sums to one by construction.
#' The eight-column matrix contains overlapping populations and should
#' not be summed or normalized as a mutually exclusive composition.
#' No hierarchical rescaling was applied to the source percentages.
#'
#' Expression values and gene identifiers were preserved from the supplied
#' count matrix. No expression normalization or gene filtering was applied.
#' Sample filtering was based on matching and proportion completeness.
#' Fifteen retained samples are marked as not passing RNA quality control
#' in the source metadata; that flag was not used for additional filtering.
#'
#' The data included here were processed and reformatted by Sergej Ruff for
#' use with QUASAR deconvolution workflows. No endorsement by the original
#' data providers is implied.
#'
#' @source
#' Gene Expression Omnibus accession GSE193141:
#' \url{https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE193141}
#'
#' Flow cytometry measurements and sample metadata were obtained from
#' Supplementary File 7 of:
#'
#' Morandini F, Rechsteiner C, Perez K, et al. (2024).
#' ATAC-clock: An aging clock based on chromatin accessibility.
#' GeroScience 46, 1789--1806.
#' \doi{10.1007/s11357-023-00986-0}
#'
#' @usage data(GSE193141)
#'
#' @keywords datasets
#'
#' @examples
#' data(GSE193141)
#'
#' names(GSE193141)
#' dim(GSE193141$bulk_expression_profiles)
#' dim(GSE193141$ground_truth_proportions)
#' dim(GSE193141$ground_truth_all_ct)
#' colnames(GSE193141$ground_truth_all_ct)
#'
#' identical(
#'   colnames(GSE193141$bulk_expression_profiles),
#'   rownames(GSE193141$ground_truth_proportions)
#' )
#'
#' identical(
#'   rownames(GSE193141$ground_truth_proportions),
#'   rownames(GSE193141$ground_truth_all_ct)
#' )
"GSE193141"


#' SDY67 PBMC deconvolution benchmark using the Scaden flow-cytometry data
#'
#' A processed peripheral blood mononuclear cell (PBMC) bulk RNA-seq
#' deconvolution dataset derived from ImmPort study SDY67, using the
#' flow-cytometry reference proportions used in the Scaden study by
#' Menden et al. (2020).
#'
#' The object contains bulk expression profiles and corresponding
#' ground-truth cell type proportions, formatted for use in QUASAR
#' deconvolution workflows.
#'
#' The underlying SDY67 study investigated immune responses to influenza
#' vaccination. Menden et al. (2020) used a subset of this study as the
#' PBMC1 benchmark, citing Zimmermann et al. (2016) as the original source.
#'
#' @format A named list containing:
#' \describe{
#'   \item{bulk_expression_profiles}{
#'     A numeric matrix or data frame containing bulk expression profiles,
#'     with features in rows and samples in columns.
#'   }
#'   \item{ground_truth_proportions}{
#'     A numeric matrix or data frame containing reference cell type
#'     proportions, with samples in rows and cell types in columns.
#'     The harmonized columns are \code{CD8Tcells}, \code{Monocytes},
#'     \code{CD4Tcells}, \code{Bcells}, \code{NK}, and \code{Unknown}.
#'   }
#' }
#'
#' @details
#' The suffix \code{_scaden} identifies the version using the
#' flow-cytometry reference data employed in the Scaden benchmark.
#' These reference proportions provide the experimental comparison for
#' evaluating expression-based cell composition estimates.
#'
#' Menden et al. (2020) describe a 12-sample PBMC1 benchmark. The dimensions
#' of the packaged object can be inspected using the examples below.
#'
#' The harmonized cell type labels have the following meanings:
#' \describe{
#'   \item{CD8Tcells}{CD8 T cells.}
#'   \item{Monocytes}{Monocytes.}
#'   \item{CD4Tcells}{CD4 T cells.}
#'   \item{Bcells}{B cells.}
#'   \item{NK}{Natural killer cells.}
#'   \item{Unknown}{
#'     An additional or unassigned category in the processed representation.
#'     Its interpretation depends on the preprocessing used to construct
#'     this object; it should not automatically be interpreted as a
#'     separately measured flow-cytometry population.
#'   }
#' }
#'
#' Sample identifiers in the expression matrix columns should correspond
#' to those in the proportion matrix rows. Column order should be checked
#' when comparing proportions with deconvolution predictions.
#'
#' The data were processed and reformatted by Sergej Ruff for use with
#' QUASAR deconvolution workflows. No endorsement by the original data
#' providers or the Scaden authors is implied.
#'
#' @source
#' Original study: ImmPort accession SDY67:
#' \url{https://www.immport.org/shared/study/SDY67}
#'
#' Scaden publication and associated resources:
#' \doi{10.1126/sciadv.aba2619}
#'
#' Related Scaden Figshare resource, titled "PBMC training data":
#' \url{https://figshare.com/s/e59a03885ec4c4d8153f} Last access: 23.10.2026, 18:52.
#'
#' The linked Figshare record describes simulated bulk training data
#' generated from four 10x Genomics single-cell PBMC datasets. It does
#' not identify itself as the SDY67 flow-cytometry reference dataset.
#'
#' @references
#' Menden, K., Marouf, M., Oller, S., Dalmia, A., Magruder, D. S.,
#' Kloiber, K., Heutink, P., and Bonn, S. (2020).
#' Deep learning-based cell composition analysis from tissue expression
#' profiles. \emph{Science Advances}, 6(30), eaba2619.
#' \doi{10.1126/sciadv.aba2619}
#'
#' Zimmermann, M. T., Oberg, A. L., Grill, D. E., Ovsyannikova, I. G.,
#' Haralambieva, I. H., Kennedy, R. B., and Poland, G. A. (2016).
#' System-Wide Associations between DNA-Methylation, Gene Expression,
#' and Humoral Immune Response to Influenza Vaccination.
#' \emph{PLOS ONE}, 11(3), e0152034.
#' \doi{10.1371/journal.pone.0152034}
#'
#' @seealso \code{\link{SDY67}}
#'
#' @usage data(SDY67_scaden)
#'
#' @keywords datasets
#'
#' @examples
#' data(SDY67_scaden)
#'
#' names(SDY67_scaden)
#' dim(SDY67_scaden$bulk_expression_profiles)
#' dim(SDY67_scaden$ground_truth_proportions)
#' colnames(SDY67_scaden$ground_truth_proportions)
#'
#' # Check sample alignment
#' identical(
#'   colnames(SDY67_scaden$bulk_expression_profiles),
#'   rownames(SDY67_scaden$ground_truth_proportions)
#' )
#'
#' # Inspect reference proportions and their row totals
#' head(SDY67_scaden$ground_truth_proportions)
#' head(rowSums(SDY67_scaden$ground_truth_proportions))
"SDY67_scaden"




#' Processed GSE107990 (Monaco II) PBMC microarray deconvolution dataset
#'
#' A processed peripheral blood mononuclear cell (PBMC) deconvolution
#' benchmark dataset derived from GEO accession GSE107990, also known
#' as Monaco II in deconvolution benchmarks.
#'
#' GSE107990 contains expression measurements from the Illumina
#' HumanHT-12 v4 microarray platform. Unlike GSE107011, commonly called
#' Monaco I, this dataset contains microarray intensities
#' rather than bulk RNA-seq measurements.
#'
#' The object contains matched expression profiles, harmonized ground-truth
#' proportions for five major immune cell types and an unknown fraction,
#' and a second proportion matrix retaining all 11 population columns
#' available for this cohort.
#'
#' The harmonized ground-truth table was obtained from the benchmark
#' resources accompanying Khatri, Machart, and Bonn (2024), the DISSECT
#' study. The 11-population table was obtained from the supplementary
#' material of Monaco et al. (2019).
#'
#' @format A named list with three elements:
#' \describe{
#'   \item{bulk_expression_profiles}{
#'     A numeric matrix with 20,908 genes and 164 bulk PBMC samples.
#'     Rows are identified by gene symbols and columns by sample
#'     identifiers, such as \code{X2_D0}.
#'     Values are gene-level summaries of non-normalized microarray
#'     signal intensities.
#'   }
#'   \item{ground_truth_proportions}{
#'     A numeric matrix with 164 samples and 6 columns:
#'     \code{Bcells}, \code{CD4Tcells}, \code{CD8Tcells},
#'     \code{Monocytes}, \code{NK}, and \code{Unknown}.
#'     Values are fractions on a 0--1 scale and sum to one per sample,
#'     within numerical precision.
#'   }
#'   \item{ground_truth_all_ct}{
#'     A numeric matrix with 164 samples and 11 population columns:
#'     \code{B Memory}, \code{B Naive}, \code{Plasmablasts},
#'     \code{T CD4}, \code{T CD8}, \code{Monocytes}, \code{DCs},
#'     \code{NK}, \code{mDCs}, \code{pDCs}, and \code{T cells}.
#'     Source percentages were divided by 100 to obtain fractions.
#'     These populations overlap, so row sums are not constrained to one.
#'   }
#' }
#'
#' @details
#' The packaged dataset contains 164 baseline samples with matching
#' expression profiles and complete values in both proportion matrices.
#' Expression column names are identical, and in the same order, to
#' the row names of both proportion matrices.
#'
#'
#' Illumina probe identifiers were mapped to Entrez Gene identifiers
#' using illuminaHumanv4.db version 1.26.0 and then to gene symbols
#' using org.Hs.eg.db version 3.23.1. Probes without an unambiguous
#' gene symbol, or with missing expression in any retained sample, were
#' excluded. Multiple retained probes mapping to the same gene were
#' combined by taking their arithmetic mean for each sample.
#' Gene symbols are stored as expression row names.
#'
#' Expression values retain their original non-normalized intensity scale.
#' No logarithmic transformation, between-sample normalization, or batch
#' correction was applied during preparation of this object.
#' These values should not be interpreted as sequencing counts.
#'
#' The six-column ground-truth matrix preserves the supplied DISSECT
#' benchmark proportions. Its correspondence to the detailed population
#' matrix was verified for every sample:
#' \describe{
#'   \item{Bcells}{
#'     The sum of \code{B Memory}, \code{B Naive}, and
#'     \code{Plasmablasts}.
#'   }
#'   \item{CD4Tcells}{
#'     The \code{T CD4} population.
#'   }
#'   \item{CD8Tcells}{
#'     The \code{T CD8} population.
#'   }
#'   \item{Monocytes}{
#'     The \code{Monocytes} population.
#'   }
#'   \item{NK}{
#'     The \code{NK} population.
#'   }
#'   \item{Unknown}{
#'     One minus the sum of the five major cell-type fractions.
#'     This is an arithmetic remainder, not a separately measured
#'     flow-cytometry population.
#'   }
#' }
#'
#' The detailed proportions were extracted from Supplementary Table S6
#' of Monaco et al. (2019), distributed as \code{mmc7.xlsx}, using its
#' second worksheet, \code{GSE107990 (Our vaccine cohort)}.
#' All 11 population columns were retained with their original names.
#'
#'
#' The data were processed and reformatted by Sergej Ruff for use with
#' QUASAR deconvolution workflows. No endorsement by the original data
#' providers is implied.
#'
#' @source
#' Bulk expression data: Gene Expression Omnibus accession GSE107990:
#' \url{https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE107990}
#'
#' Microarray platform: Illumina HumanHT-12 v4, GEO accession GPL10558:
#' \url{https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GPL10558}
#'
#' Harmonized six-column ground truth: benchmark resources accompanying
#' Khatri, Machart, and Bonn (2024), DISSECT:
#' \doi{10.1186/s13059-024-03251-5}
#'
#' Detailed 11-population ground truth: Monaco et al. (2019),
#' Supplementary Table S6, second worksheet:
#' \doi{10.1016/j.celrep.2019.01.041}
#'
#' @references
#' Monaco, G., Lee, B., Xu, W., Mustafah, S., Hwang, Y. Y.,
#' Carre, C., et al. (2019).
#' RNA-Seq signatures normalized by mRNA abundance allow absolute
#' deconvolution of human immune cell types.
#' \emph{Cell Reports}, 26(6), 1627--1640.e7.
#' \doi{10.1016/j.celrep.2019.01.041}
#'
#' Khatri, R., Machart, P., and Bonn, S. (2024).
#' DISSECT: deep semi-supervised consistency regularization for accurate
#' cell type fraction and gene expression estimation.
#' \emph{Genome Biology}, 25, 112.
#' \doi{10.1186/s13059-024-03251-5}
#'
#' @seealso
#' \code{\link{GSE107011}} for the Monaco1 bulk RNA-seq benchmark.
#'
#' @usage data(GSE107990)
#'
#' @keywords datasets
#'
#' @examples
#' data(GSE107990)
#'
#' names(GSE107990)
#' dim(GSE107990$bulk_expression_profiles)
#' dim(GSE107990$ground_truth_proportions)
#' dim(GSE107990$ground_truth_all_ct)
#'
#' # Gene symbols and cell-type labels
#' head(rownames(GSE107990$bulk_expression_profiles))
#' colnames(GSE107990$ground_truth_proportions)
#' colnames(GSE107990$ground_truth_all_ct)
#'
#' # Check sample alignment
#' identical(
#'   colnames(GSE107990$bulk_expression_profiles),
#'   rownames(GSE107990$ground_truth_proportions)
#' )
#' identical(
#'   colnames(GSE107990$bulk_expression_profiles),
#'   rownames(GSE107990$ground_truth_all_ct)
#' )
#'
#' # The harmonized proportions sum to one
#' head(rowSums(GSE107990$ground_truth_proportions))
#'
#' # Detailed populations include overlapping groups
#' head(GSE107990$ground_truth_all_ct)
"GSE107990"

#' Load the COVID-19 PBMC immune reference (train, test, or healthy split)
#'
#' Loads one part of a donor-balanced 50/50 split of a COVID-19 peripheral-blood
#' immune dataset, shipped in \code{inst/extdata}. The train and test halves
#' balance mild and severe COVID-19 donors so neither split is enriched for
#' disease severity. A third reference built only from healthy (non-diseased)
#' donors is provided for reference-mismatch experiments.
#'
#' @param which Which reference to load: \code{"train"} (default),
#'   \code{"test"}, or \code{"healthy"}.
#' @param project Project name for the resulting object. Defaults to
#'   \code{paste0(which, "_cov")}.
#'
#' @return A \code{\link[SeuratObject]{Seurat}} object with a single \code{counts}
#'   layer, cell-type identities set, and \code{meta.data} columns
#'   \code{cell_type} and \code{donor_id}.
#'
#' @details
#' To keep the packaged \code{.rds} files under 100 MB, the sparse count matrix is
#' stored in CSC form with its values as 32-bit floats. On load the values are
#' read back into double precision, accurate to ~7 significant digits relative to
#' the source; no genes or cells are dropped. \code{donor_id} is retained for
#' deconvolution methods that require per-subject information, e.g. MuSiC.
#'
#' The healthy reference contains cells from donors annotated as non-diseased
#' only. It is intended for experiments in which a reference that does not match
#' the disease composition of the mixtures is used for deconvolution, and it may
#' therefore lack cell types present in the benchmark ground truth.
#'
#' Source: CELLxGENE collection
#' \url{https://cellxgene.cziscience.com/collections/b9fc3d70-5a72-4479-a046-c2cc1ab19efc}.
#'
#' @examples
#' \dontrun{
#' train   <- load_cov_imm()             # training split (default)
#' test    <- load_cov_imm("test")       # test split
#' healthy <- load_cov_imm("healthy")    # healthy-donor reference
#' }
#'
#' @importFrom methods new
#' @importClassesFrom Matrix dgCMatrix
#' @importFrom SeuratObject CreateSeuratObject Idents `Idents<-`
#' @export
load_cov_imm <- function(which = c("train", "test", "healthy"), project = NULL) {
  which <- match.arg(which)
  if (is.null(project)) project <- paste0(which, "_cov")

  chunked <- c(healthy = 3L)

  read_payload <- function(file) {
    d <- readRDS(file)
    x <- readBin(d$x, "double", n = d$n, size = 4L)
    list(
      m = new("dgCMatrix", i = d$i, p = d$p, x = x,
              Dim = d$Dim, Dimnames = d$dn),
      meta = d$meta
    )
  }

  resolve <- function(fname) {
    f <- system.file("extdata", fname, package = "QuasarDeconData")
    if (!nzchar(f) || !file.exists(f))
      stop("Packaged file not found: ", fname, call. = FALSE)
    f
  }

  if (which %in% names(chunked)) {
    n_chunks <- chunked[[which]]
    files <- sprintf("%s_cov_%d.rds", which, seq_len(n_chunks))
    parts <- lapply(files, function(fn) read_payload(resolve(fn)))

    genes <- rownames(parts[[1]]$m)
    if (!all(vapply(parts, function(p) identical(rownames(p$m), genes), logical(1))))
      stop("Packaged chunks do not share the same gene set.", call. = FALSE)

    m <- do.call(cbind, lapply(parts, `[[`, "m"))
    meta <- do.call(rbind, lapply(parts, `[[`, "meta"))
    rm(parts)

    if (!identical(colnames(m), rownames(meta)))
      stop("Reassembled counts and metadata are out of sync.", call. = FALSE)
  } else {
    p <- read_payload(resolve(paste0(which, "_cov.rds")))
    m <- p$m
    meta <- p$meta
    rm(p)
  }

  obj <- CreateSeuratObject(counts = m, meta.data = meta,
                            assay = "RNA", project = project)
  Idents(obj) <- obj$cell_type
  obj
}



#' Load COVID-19 PBMC pseudo-bulk benchmark datasets
#'
#' Loads pseudo-bulk expression profiles generated from the COVID-19 PBMC
#' immune atlas. The ten test-split datasets are intended for deconvolution
#' benchmarks using the corresponding \code{train_cov} reference; the
#' pseudo-bulk data generated from the training split, and from the
#' healthy-only reference split, can be loaded as well.
#'
#' Each packaged test file contains 1000 pseudo-bulk samples and their matching
#' ground-truth cell-type proportions. The training pseudo-bulk data contains
#' 10000 samples.
#'
#' @param which Which pseudo-bulk dataset to load. One of:
#'   \itemize{
#'     \item \code{"all"} (the default): all ten test pseudo-bulk datasets.
#'     \item an integer from \code{1} to \code{10}: a single test dataset.
#'     \item \code{"train"}: the pseudo-bulk data built from the training split,
#'       reassembled from its packaged chunks into a single dataset.
#'     \item \code{"healthy"}: the pseudo-bulk data built from the healthy-only
#'       training split, reassembled from its packaged chunks into a single
#'       dataset.
#'   }
#'
#' @return If \code{which = "all"}, a named list of length 10. Each element is a
#'   pseudo-bulk dataset containing:
#'   \itemize{
#'     \item \code{bulk_expression_profiles}: pseudo-bulk expression matrix.
#'     \item \code{ground_truth_proportions}: true cell-type proportions for the
#'       pseudo-bulk samples.
#'   }
#'
#'   If \code{which} is an integer from \code{1} to \code{10},
#'   \code{"train"}, or \code{"healthy"}, a single pseudo-bulk dataset with
#'   those same two elements is returned.
#'
#' @details
#' The test files are stored in \code{inst/extdata} as
#' \code{cov_pbulk_1.rds}, \code{cov_pbulk_2.rds}, ...,
#' \code{cov_pbulk_10.rds}. They were created from \code{test_cov} and are
#' designed to be used with \code{train_cov} for deconvolution benchmarking.
#'
#' The training pseudo-bulk data is split across
#' \code{training_pb_cov_1.rds} ... \code{training_pb_cov_10.rds}, and the
#' healthy-only pseudo-bulk data across
#' \code{healthy_pb_cov_1.rds} ... \code{healthy_pb_cov_10.rds}, to keep
#' individual files small. \code{which = "train"} and \code{which = "healthy"}
#' load all chunks and bind them back into one dataset, so the split is not
#' visible to the caller. Sample order is preserved.
#'
#' The healthy-only pseudo-bulk data is intended for reference-mismatch
#' experiments, in which a reference built from healthy donors only is used to
#' deconvolve mixtures containing diseased samples.
#'
#' Note that \code{which = "all"} returns only the ten test datasets; the
#' training and healthy pseudo-bulk data must be requested explicitly.
#'
#' @examples
#' \dontrun{
#' pbulks <- load_cov_pbulk()
#'
#' pbulk1 <- load_cov_pbulk(1)
#' expr <- pbulk1$bulk_expression_profiles
#' prop <- pbulk1$ground_truth_proportions
#'
#' train_pbulk <- load_cov_pbulk("train")
#' healthy_pbulk <- load_cov_pbulk("healthy")
#' }
#'
#' @export
load_cov_pbulk <- function(which = "all") {
  n_files <- 10L
  n_train_chunks <- 10L
  n_healthy_chunks <- 10L
  valid_ids <- seq_len(n_files)

  err_msg <- paste(
    "`which` must be \"all\", \"train\", \"healthy\",",
    "or a single integer from 1 to 10."
  )

  reassemble <- FALSE

  if (identical(which, "all")) {
    ids <- valid_ids
    files <- paste0("cov_pbulk_", ids, ".rds")
    nms <- paste0("cov_pbulk_", ids)
    return_single <- FALSE
  } else if (identical(which, "train")) {
    ids <- seq_len(n_train_chunks)
    files <- paste0("training_pb_cov_", ids, ".rds")
    nms <- paste0("cov_pbulk_train_", ids)
    return_single <- FALSE
    reassemble <- TRUE
  } else if (identical(which, "healthy")) {
    ids <- seq_len(n_healthy_chunks)
    files <- paste0("healthy_pb_cov_", ids, ".rds")
    nms <- paste0("cov_pbulk_healthy_", ids)
    return_single <- FALSE
    reassemble <- TRUE
  } else {
    if (length(which) != 1L) {
      stop(err_msg, call. = FALSE)
    }

    id <- suppressWarnings(as.integer(which))

    if (is.na(id) || !id %in% valid_ids ||
        as.character(id) != as.character(which)) {
      stop(err_msg, call. = FALSE)
    }

    files <- paste0("cov_pbulk_", id, ".rds")
    nms <- paste0("cov_pbulk_", id)
    return_single <- TRUE
  }

  paths <- vapply(
    files,
    function(x) {
      system.file("extdata", x, package = "QuasarDeconData")
    },
    character(1)
  )

  missing_files <- !nzchar(paths) | !file.exists(paths)

  if (any(missing_files)) {
    stop(
      "Packaged pseudo-bulk file(s) not found: ",
      paste(files[missing_files], collapse = ", "),
      call. = FALSE
    )
  }

  out <- lapply(paths, readRDS)
  names(out) <- nms

  required_names <- c("bulk_expression_profiles", "ground_truth_proportions")

  valid_structure <- vapply(
    out,
    function(x) all(required_names %in% names(x)),
    logical(1)
  )

  if (any(!valid_structure)) {
    stop(
      "Unexpected pseudo-bulk structure in: ",
      paste(names(out)[!valid_structure], collapse = ", "),
      call. = FALSE
    )
  }

  if (reassemble) {
    sample_axis <- attr(out[[1]], "sample_axis")
    if (is.null(sample_axis)) sample_axis <- "cols"

    expr_parts <- lapply(out, `[[`, "bulk_expression_profiles")
    prop_parts <- lapply(out, `[[`, "ground_truth_proportions")

    expr <- if (identical(sample_axis, "cols")) {
      do.call(cbind, expr_parts)
    } else {
      do.call(rbind, expr_parts)
    }
    prop <- do.call(rbind, prop_parts)

    rm(out, expr_parts, prop_parts)

    n_expr <- if (identical(sample_axis, "cols")) ncol(expr) else nrow(expr)
    if (n_expr != nrow(prop)) {
      stop(
        "Reassembled data is inconsistent: ",
        n_expr, " expression samples vs ", nrow(prop), " proportion rows.",
        call. = FALSE
      )
    }

    return(list(
      bulk_expression_profiles = expr,
      ground_truth_proportions = prop
    ))
  }

  if (return_single) {
    out[[1]]
  } else {
    out
  }
}